                elif re.search(r'\bspin_lock_irq\s*\(',bl): kind="irq"
                elif re.search(r'\bspin_lock_bh\s*\(',bl): kind="bh"
                else: kind="other"
                out.write(f"{f}\t{h}\t{ln}\t{kind}\t{lnm}\n")
out.close()
print("defs found",found,"notfound",notfound,"handlers-with-locks",withlocks)
